#include <iostream>

#define NAME_SIZE 32

using std::cout;
using std::endl;

struct __Student
{
    char    szName[NAME_SIZE];
    int     iKorean;
    int     iMath;
    int     iEnglish;
    int     iTotal;
    float   fAverage;
};

int main()
{
    __Student tStudent = { "Chanyeon", 90, 85, 80, 0, 0.f };

    void* pVoid = &tStudent;

    __Student* pStudent = (__Student*)pVoid;

    pStudent->iTotal = pStudent->iKorean + pStudent->iMath + pStudent->iEnglish;
    pStudent->fAverage = pStudent->iTotal / 3.f;

    cout << "Name: " << pStudent->szName << endl;
    cout << "Total: " << pStudent->iTotal << endl;
    cout << "Average: " << pStudent->fAverage << endl;

    return 0;
}
